description:
Lesson 1.04's golden rule: `Unload` undoes everything `DriverEntry` did, in reverse order, and a `DriverEntry` that fails undoes what it already did. Write a small helper that enforces this, and that driver code can be written against:

```cpp
class Setup
{
public:
    void done(const std::string& step, std::function<void()> undo);   // a step succeeded; remember how to undo it
    void rollback();                                                    // undo every remembered step, newest first, once
    std::size_t count() const;
};

std::vector<std::string> runDriverEntry(const std::vector<std::string>& steps, int failAt, std::vector<std::string>& log);
```

- `Setup::rollback` calls the undo functions in **reverse** order and forgets them, so a second call does nothing. `count` is how many steps are remembered.
- `runDriverEntry` simulates a `DriverEntry`: for each step in order, if its index equals `failAt`, it logs `"fail <step>"`, rolls back, and returns an empty list; otherwise it logs `"do <step>"` and remembers an undo that logs `"undo <step>"`. If all steps succeed, it returns the steps that `Unload` must undo, in the order `Unload` must undo them (newest first), without undoing anything yet.

starter.solution.cpp:
#include <functional>
#include <string>
#include <vector>

class Setup
{
public:
    void done(const std::string& step, std::function<void()> undo) {}
    void rollback() {}
    std::size_t count() const { return 0; }
};

std::vector<std::string> runDriverEntry(const std::vector<std::string>& steps, int failAt, std::vector<std::string>& log) { return {}; }

solution.solution.cpp:
#include <functional>
#include <string>
#include <utility>
#include <vector>

class Setup
{
public:
    void done(const std::string& step, std::function<void()> undo) { m_steps.push_back({ step, std::move(undo) }); }

    void rollback()
    {
        while (!m_steps.empty())
        {
            auto undo{ std::move(m_steps.back().second) };
            m_steps.pop_back();
            if (undo) undo();
        }
    }

    std::size_t count() const { return m_steps.size(); }

private:
    std::vector<std::pair<std::string, std::function<void()>>> m_steps;
};

std::vector<std::string> runDriverEntry(const std::vector<std::string>& steps, int failAt, std::vector<std::string>& log)
{
    Setup setup;
    for (std::size_t i{ 0 }; i < steps.size(); ++i)
    {
        const std::string& step{ steps[i] };
        if (static_cast<int>(i) == failAt)
        {
            log.push_back("fail " + step);
            setup.rollback();
            return {};
        }
        log.push_back("do " + step);
        setup.done(step, [&log, step] { log.push_back("undo " + step); });
    }
    return std::vector<std::string>(steps.rbegin(), steps.rend());
}

unitTests:
using Log = std::vector<std::string>;
const Log steps{ "allocate context", "create device", "create symbolic link", "register callback" };
TEST("rollback in reverse, once") {
    Log log; Setup s; s.done("a", [&] { log.push_back("undo a"); }); s.done("b", [&] { log.push_back("undo b"); }); CHECK_EQ(s.count(), std::size_t{ 2 });
    s.rollback(); CHECK_EQ(log, (Log{ "undo b", "undo a" })); s.rollback(); CHECK_EQ(log.size(), std::size_t{ 2 }); CHECK_EQ(s.count(), std::size_t{ 0 });
}
TEST("a failure halfway") {
    Log log; CHECK(runDriverEntry(steps, 2, log).empty());
    CHECK_EQ(log, (Log{ "do allocate context", "do create device", "fail create symbolic link", "undo create device", "undo allocate context" }));
}
TEST("failing at the start undoes nothing") { Log log; runDriverEntry(steps, 0, log); CHECK_EQ(log, (Log{ "fail allocate context" })); }
TEST("success leaves the work to Unload") {
    Log log; const Log unload = runDriverEntry(steps, -1, log);
    CHECK_EQ(log.size(), std::size_t{ 4 }); CHECK_EQ(unload, (Log{ "register callback", "create symbolic link", "create device", "allocate context" }));
}

